use super::decide::{Analysis, Kind};
use super::Source;

const HEADER: &str = "\
# fixups.yaml — the filter file (-C) for building one schema database from this
# snapshot with protoback:
#
#   protoback -I . --schema-db-out=DB.desc -C fixups.yaml .
#
# with the options your input needs (its descriptor, a profile).
#
# GENERATED by `protosets advise`: do not edit by hand. Run it again after each
# extraction; `protosets advise --check` tells whether this file is current.
#
# Why at all: this snapshot is the union of the descriptors of many sources,
# built at different times, and nothing is ever removed from it. A schema
# database holds one version of each symbol, so wherever two files conflict,
# one goes. The rule: the newer one stays, unless the older one holds
# everything the newer one does, identically, and more. A file's age is the
# build time of the newest source that holds it; for a file no source lists,
# the time of the commit that last wrote it (it can't hold anything built
# later).
#
# prune: `path:` for a ~N copy (it has the same descriptor name as the file
# kept), `file:` (the descriptor name) for everything else, so that the file
# is pruned however it is reached, including through an importer.
#
# move: OLD: NEW prunes OLD, and every import of OLD becomes an import of NEW
# (protoback spec 0445).
";

const PRUNE_SECTIONS: [(Kind, &str, &str); 3] = [
    (
        Kind::Copies,
        "Identical copies",
        "One binary embeds the same file twice, once without json_name: protosets keeps both, \
         as <name>~N.pb. Keeping one loses nothing.",
    ),
    (
        Kind::Versions,
        "Older versions under the same name",
        "Two sources hold different versions of one file: protosets keeps both, as \
         <name>~N.pb. The older goes.",
    ),
    (
        Kind::Numbers,
        "Reused extension numbers",
        "Two extensions with one number on one message: a number retired and given to a new \
         extension. The older goes.",
    ),
];

const MOVE_SECTIONS: [(Kind, &str, &str); 2] = [
    (
        Kind::Moves,
        "Moved or renamed files (forward)",
        "A newer source has the same symbols under another path. The older file goes, and its \
         importers, if any are still in the snapshot, import the newer one instead. Symbols \
         only the older file had are lost to them: protoback says which (W24).",
    ),
    (
        Kind::Backward,
        "Split files (backward)",
        "A newer file holds part of an older one, identically, and nothing of its own. The \
         older file holds symbols nothing else defines, so it stays; the newer one goes, and \
         its importers import the older one. Nothing is lost.",
    ),
];

/// A kind's title, as its section in `fixups.yaml` has it.
pub fn kind_title(kind: Kind) -> &'static str {
    PRUNE_SECTIONS
        .iter()
        .chain(MOVE_SECTIONS.iter())
        .find(|(k, _, _)| *k == kind)
        .map(|(_, title, _)| *title)
        .unwrap_or("?")
}

/// The text of `fixups.yaml`.
pub fn render(a: &Analysis, sources: &[Source]) -> String {
    let mut out = String::from(HEADER);
    out.push_str(&stamp(sources));
    out.push_str("\nprune:\n");
    for (kind, title, text) in PRUNE_SECTIONS {
        section(&mut out, a, kind, title, text, kind != Kind::Copies);
    }
    out.push_str("\nmove:\n");
    for (kind, title, text) in MOVE_SECTIONS {
        section(&mut out, a, kind, title, text, true);
    }
    out
}

/// The sources the file was computed from, one identity per line, sorted
/// (spec 0454 S8).
pub fn stamp(sources: &[Source]) -> String {
    let mut ids: Vec<&str> = sources.iter().map(|s| s.identity.as_str()).collect();
    ids.sort_unstable();
    ids.dedup();
    let mut out = String::from("#\n# computed from:\n");
    for id in ids {
        out.push_str(&format!("#   {id}\n"));
    }
    out
}

/// The identities a generated file's stamp names, or `None` without one.
/// Reads both `fixups.yaml`'s comment block and `STATUS.md`'s code block.
pub fn parse_stamp(text: &str) -> Option<std::collections::BTreeSet<String>> {
    let mut lines = text.lines().skip_while(|l| l.trim() != "# computed from:");
    lines.next()?;
    Some(
        lines
            .map_while(|l| l.strip_prefix("#   "))
            .map(|id| id.to_string())
            .collect(),
    )
}

fn section(out: &mut String, a: &Analysis, kind: Kind, title: &str, text: &str, comments: bool) {
    let mut entries: Vec<_> = a.decisions.iter().filter(|d| d.kind == kind).collect();
    if entries.is_empty() {
        return;
    }
    entries.sort_by_key(|d| d.directive.render());
    out.push_str(&format!("\n  # --- {title} ({}) ---\n", entries.len()));
    for line in wrap(text, 76) {
        out.push_str(&format!("  # {line}\n"));
    }
    for d in entries {
        if comments {
            out.push_str(&format!("\n  # {}\n", d.comment));
        }
        out.push_str(&format!("  - {}\n", d.directive.render()));
    }
}

fn wrap(text: &str, width: usize) -> Vec<String> {
    let mut lines = Vec::new();
    let mut cur = String::new();
    for w in text.split_whitespace() {
        if !cur.is_empty() && cur.len() + 1 + w.len() > width {
            lines.push(std::mem::take(&mut cur));
        }
        if !cur.is_empty() {
            cur.push(' ');
        }
        cur.push_str(w);
    }
    if !cur.is_empty() {
        lines.push(cur);
    }
    lines
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::advise::decide::{Decision, Directive};

    #[test]
    fn sections_and_stamp() {
        let a = Analysis {
            decisions: vec![
                Decision {
                    directive: Directive::PrunePath("a~2.pb".into()),
                    kind: Kind::Copies,
                    comment: "c".into(),
                },
                Decision {
                    directive: Directive::Move {
                        old: "o.proto".into(),
                        new: "n.proto".into(),
                    },
                    kind: Kind::Moves,
                    comment: "moved".into(),
                },
            ],
            ..Default::default()
        };
        let src = |id: &str| Source {
            identity: id.into(),
            build_time: 0,
            group: None,
            paths: Default::default(),
            metadata: vec![],
        };
        let text = render(&a, &[src("b"), src("a"), src("b")]);
        assert!(text.contains("# computed from:\n#   a\n#   b\n"));
        assert_eq!(
            parse_stamp(&text),
            Some(["a".to_string(), "b".to_string()].into_iter().collect())
        );
        assert_eq!(parse_stamp("no stamp"), None);
        assert!(text.contains("  # --- Identical copies (1) ---\n"));
        assert!(text.contains("  - path:a~2.pb\n"));
        assert!(!text.contains("# c\n"), "copies have no per-entry comment");
        assert!(text.contains("\n  # moved\n  - o.proto: n.proto\n"));
        // It is valid YAML with the two lists.
        let v: serde_yaml::Value = serde_yaml::from_str(&text).unwrap();
        assert_eq!(v["prune"].as_sequence().unwrap().len(), 1);
        assert_eq!(v["move"][0]["o.proto"].as_str(), Some("n.proto"));
    }
}
